scan_linter_check.script:
(function(engine) {
    global.EcsGlideRecord.runBulkCheck(engine, {
        ruleId: 'SN-GR-002',
        tier: 'confirmed',
        bulkMethod: 'deleteMultiple',
        perRecordMethod: 'deleteRecord',
        title: 'GlideRecord delete with no query conditions',
        recommendation: 'Add query conditions that limit the delete to the intended records, and test them with ' +
            'a count (GlideAggregate) first. If deleting every record really is intended, mute this finding with a reason.'
    });
})(engine);
